CREATE OR REPLACE FUNCTION public.claim_kipi_journal_internal(p_id uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN UPDATE public.kipi_journals SET lease_until=now()+interval '5 minutes' WHERE id=p_id AND (lease_until IS NULL OR lease_until<now()) AND processing_status NOT IN ('indexed','indexed_with_gaps'); RETURN FOUND; END $$;
REVOKE ALL ON FUNCTION public.claim_kipi_journal_internal(uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.claim_kipi_journal_internal(uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.process_listing_visibility_notifications() RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s public.listing_subscriptions; days_left integer; kind text; event text; inserted uuid; n integer:=0; BEGIN FOR s IN SELECT a.* FROM public.listing_subscriptions a WHERE a.expires_at<now()+interval '15 days' AND NOT EXISTS(SELECT 1 FROM public.listing_visibility_events e WHERE e.subscription_id=a.id AND e.event_key=a.id::text||':'||a.expires_at::text||':suspended') ORDER BY a.expires_at DESC LIMIT 500 LOOP days_left:=(s.expires_at AT TIME ZONE 'Africa/Nairobi')::date-(now() AT TIME ZONE 'Africa/Nairobi')::date; kind:=CASE WHEN s.expires_at<=now() THEN 'suspended' WHEN s.period_type='introductory' AND days_left IN (14,7,3) THEN 'reminder_'||days_left WHEN s.period_type='paid' AND days_left IN (7,3) THEN 'reminder_'||days_left END; IF kind IS NOT NULL THEN event:=s.id::text||':'||s.expires_at::text||':'||kind; inserted:=NULL; INSERT INTO public.listing_visibility_events(subscription_id,owner_id,event_key,kind) VALUES(s.id,s.owner_id,event,kind) ON CONFLICT(event_key) DO NOTHING RETURNING id INTO inserted; IF inserted IS NOT NULL THEN INSERT INTO public.notifications(user_id,kind,title,body,listing_id) VALUES(s.owner_id,'listing_visibility',CASE WHEN kind='suspended' THEN 'Listing visibility suspended' ELSE 'Listing renewal due in '||days_left||' days' END,'Renew this listing for KSh 1,000 / 30 days from your dashboard. Your listing and documents have not been deleted.',s.ip_listing_id); n:=n+1; END IF; END IF; END LOOP; RETURN n; END $$;
CREATE UNIQUE INDEX kipi_discovery_single_flight ON public.kipi_sync_runs((true)) WHERE status='running';